/**
 * YouTube Transcript Extractor (auto-opens the transcript panel)
 * ----------------------------------------------------------------
 * HOW TO USE:
 * 1. Open the YouTube video (just the normal watch page, nothing pre-clicked).
 * 2. Open DevTools (F12 or Ctrl+Shift+I / Cmd+Opt+I) -> "Console" tab.
 * 3. Paste this entire script and press Enter. A small movable panel appears.
 * 4. Click "🔍 Open + Extract Transcript" — it will click "...more" and
 *    "Show transcript" for you, wait for the panel to load, then extract it.
 * 5. Click "💾 Save as .txt" (or "📋 Copy to Clipboard").
 *
 * Notes:
 * - Only interacts with buttons/text already on the page you're viewing;
 *   it doesn't call any private YouTube API.
 * - Builds all UI via document.createElement (never innerHTML), because
 *   YouTube enforces a Trusted Types CSP that blocks innerHTML string
 *   assignment from injected/console scripts.
 * - If a video has no transcript available, or YouTube changes its layout,
 *   the auto-open step may fail — the panel will tell you, and you can
 *   still open the transcript manually and click Extract again.
 */
(function () {
  'use strict';

  const PANEL_ID = 'yt-transcript-extractor-panel';
  const existingPanel = document.getElementById(PANEL_ID);
  if (existingPanel) existingPanel.remove();

  // ---------------- Shadow-DOM-aware query helpers ----------------
  function deepQueryAll(selector, root) {
    root = root || document;
    const results = new Set();
    const queue = [root];
    while (queue.length) {
      const node = queue.shift();
      if (node.querySelectorAll) {
        node.querySelectorAll(selector).forEach((el) => results.add(el));
        node.querySelectorAll('*').forEach((el) => {
          if (el.shadowRoot) queue.push(el.shadowRoot);
        });
      }
    }
    return Array.from(results);
  }

  function deepQuery(selector, root) {
    // Fast path first (works for the vast majority of YouTube's DOM).
    const fast = (root || document).querySelector
      ? (root || document).querySelector(selector)
      : null;
    if (fast) return fast;
    const all = deepQueryAll(selector, root);
    return all.length ? all[0] : null;
  }

  function delay(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  function waitForCondition(conditionFn, timeout, interval) {
    timeout = timeout || 8000;
    interval = interval || 250;
    return new Promise((resolve, reject) => {
      const start = Date.now();
      const timer = setInterval(() => {
        const result = conditionFn();
        if (result) {
          clearInterval(timer);
          resolve(result);
        } else if (Date.now() - start > timeout) {
          clearInterval(timer);
          reject(new Error('Timed out.'));
        }
      }, interval);
    });
  }

  // ---------------- Finding the relevant buttons/elements ----------------
  function findTranscriptSegmentElements() {
    return deepQueryAll('transcript-segment-view-model, ytd-transcript-segment-renderer');
  }

  function findMoreButton() {
    return (
      deepQuery('ytd-watch-metadata tp-yt-paper-button#expand') ||
      deepQuery('tp-yt-paper-button#expand')
    );
  }

  function findShowTranscriptButton() {
    return (
      deepQuery('ytd-video-description-transcript-section-renderer button') ||
      deepQuery('button[aria-label="Show transcript"]')
    );
  }

  // ---------------- Auto-open the transcript panel ----------------
  async function autoOpenTranscriptPanel(statusCb) {
    if (findTranscriptSegmentElements().length > 0) return true;

    statusCb('Opening transcript panel...');

    const tryClickShowTranscript = () => {
      const btn = findShowTranscriptButton();
      if (btn) {
        btn.click();
        return true;
      }
      return false;
    };

    // Attempt 1: click "Show transcript" directly.
    let clicked = tryClickShowTranscript();

    if (!clicked) {
      // Attempt 2: expand description ("...more") first, then retry.
      statusCb('Expanding description...');
      const moreBtn = findMoreButton();
      if (moreBtn) {
        moreBtn.click();
        await delay(600);
        clicked = tryClickShowTranscript();
      }
    }

    if (!clicked) {
      statusCb(
        'Could not find the "Show transcript" button automatically. This video may not have a transcript, or the button is in a different place — try opening it manually, then click Extract again.'
      );
      return false;
    }

    statusCb('Waiting for transcript to load...');
    try {
      await waitForCondition(() => findTranscriptSegmentElements().length > 0, 8000, 300);
      return true;
    } catch (e) {
      statusCb('Transcript panel opened but no lines loaded — this video may not have a transcript.');
      return false;
    }
  }

  // ---------------- Extraction ----------------
  function extractTranscript() {
    const segments = [];

    findTranscriptSegmentElements().forEach((el) => {
      let time = '';
      let text = '';

      // Newer "view model" layout
      const newTime = el.querySelector('.ytwTranscriptSegmentViewModelTimestamp');
      const newText = el.querySelector('span[role="text"], .ytAttributedStringHost');
      if (newTime || newText) {
        time = newTime ? newTime.textContent.trim() : '';
        text = newText ? newText.textContent.trim() : '';
      }

      // Older layout fallback
      if (!text) {
        const oldTime = el.querySelector('.segment-timestamp');
        const oldText = el.querySelector('.segment-text');
        if (oldTime || oldText) {
          time = oldTime ? oldTime.textContent.trim() : '';
          text = oldText ? oldText.textContent.trim() : '';
        }
      }

      if (text) segments.push({ time, text });
    });

    return segments;
  }

  function formatPlain(segments) {
    return segments.map((s) => s.text).join(' ');
  }

  function formatTimestamped(segments) {
    return segments.map((s) => `[${s.time}] ${s.text}`).join('\n');
  }

  function getVideoTitle() {
    let title = document.title.replace(/\s*-\s*YouTube\s*$/, '').trim();
    if (!title) title = 'youtube_transcript';
    return title.replace(/[\\/:*?"<>|]/g, '_').slice(0, 100);
  }

  // ---------------- UI (built via DOM API only — no innerHTML) ----------------
  function makeEl(tag, cssText) {
    const node = document.createElement(tag);
    if (cssText) node.style.cssText = cssText;
    return node;
  }

  const BTN_STYLE = `
    display:block;
    width:100%;
    margin-bottom:8px;
    padding:8px 10px;
    background:#3ea6ff;
    color:#0f0f0f;
    border:none;
    border-radius:6px;
    font-weight:600;
    cursor:pointer;
    user-select:none;
    font-size:13px;
  `;

  const panel = makeEl(
    'div',
    `
    position: fixed;
    top: 80px;
    right: 20px;
    width: 300px;
    background: #212121;
    color: #f1f1f1;
    border-radius: 10px;
    box-shadow: 0 4px 20px rgba(0,0,0,0.5);
    z-index: 999999;
    font-family: Roboto, Arial, sans-serif;
    font-size: 13px;
    overflow: hidden;
    user-select: none;
  `
  );
  panel.id = PANEL_ID;

  // Header
  const header = makeEl(
    'div',
    `
    background:#0f0f0f;
    padding:10px 12px;
    cursor:move;
    display:flex;
    justify-content:space-between;
    align-items:center;
  `
  );
  const title = makeEl('span', 'font-weight:600;');
  title.textContent = '📝 Transcript Extractor';
  const closeBtn = makeEl('span', 'cursor:pointer; padding:0 4px;');
  closeBtn.textContent = '✕';
  header.appendChild(title);
  header.appendChild(closeBtn);

  // Body
  const body = makeEl('div', 'padding:12px;');

  const statusEl = makeEl('div', 'margin-bottom:10px; color:#aaa; line-height:1.4;');
  statusEl.textContent = 'Click "Open + Extract Transcript" to begin.';

  const label = makeEl(
    'label',
    'display:flex; align-items:center; gap:6px; margin-bottom:10px; cursor:pointer;'
  );
  const tsCheckbox = document.createElement('input');
  tsCheckbox.type = 'checkbox';
  tsCheckbox.checked = true;
  const labelText = document.createTextNode('Include timestamps');
  label.appendChild(tsCheckbox);
  label.appendChild(labelText);

  const extractBtn = makeEl('button', BTN_STYLE);
  extractBtn.textContent = '🔍 Open + Extract Transcript';

  const copyBtn = makeEl('button', BTN_STYLE);
  copyBtn.textContent = '📋 Copy to Clipboard';
  copyBtn.disabled = true;

  const saveBtn = makeEl('button', BTN_STYLE);
  saveBtn.textContent = '💾 Save as .txt';
  saveBtn.disabled = true;

  body.appendChild(statusEl);
  body.appendChild(label);
  body.appendChild(extractBtn);
  body.appendChild(copyBtn);
  body.appendChild(saveBtn);

  panel.appendChild(header);
  panel.appendChild(body);
  document.body.appendChild(panel);

  // ---------------- Logic ----------------
  let lastSegments = [];

  function currentText() {
    return tsCheckbox.checked ? formatTimestamped(lastSegments) : formatPlain(lastSegments);
  }

  function setStatus(msg) {
    statusEl.textContent = msg;
  }

  extractBtn.addEventListener('click', async () => {
    extractBtn.disabled = true;
    copyBtn.disabled = true;
    saveBtn.disabled = true;

    const opened = await autoOpenTranscriptPanel(setStatus);

    if (opened) {
      lastSegments = extractTranscript();
      if (lastSegments.length === 0) {
        setStatus('Transcript panel is open, but no lines were found.');
      } else {
        setStatus(`Extracted ${lastSegments.length} lines.`);
        copyBtn.disabled = false;
        saveBtn.disabled = false;
      }
    }

    extractBtn.disabled = false;
  });

  copyBtn.addEventListener('click', async () => {
    const text = currentText();
    try {
      await navigator.clipboard.writeText(text);
      setStatus(`Copied ${lastSegments.length} lines to clipboard!`);
    } catch (e) {
      const ta = document.createElement('textarea');
      ta.value = text;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand('copy');
      document.body.removeChild(ta);
      setStatus(`Copied ${lastSegments.length} lines to clipboard (fallback method).`);
    }
  });

  saveBtn.addEventListener('click', () => {
    const text = currentText();
    const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${getVideoTitle()}_transcript.txt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    setStatus(`Saved ${lastSegments.length} lines as .txt file.`);
  });

  closeBtn.addEventListener('click', () => panel.remove());

  // ---------------- Draggable panel ----------------
  let isDragging = false;
  let offsetX = 0;
  let offsetY = 0;

  header.addEventListener('mousedown', (e) => {
    isDragging = true;
    const rect = panel.getBoundingClientRect();
    offsetX = e.clientX - rect.left;
    offsetY = e.clientY - rect.top;
    e.preventDefault();
  });

  document.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
    panel.style.left = e.clientX - offsetX + 'px';
    panel.style.top = e.clientY - offsetY + 'px';
    panel.style.right = 'auto';
  });

  document.addEventListener('mouseup', () => {
    isDragging = false;
  });
})();

